let selectedWeek=null;const color=n=>n===0?'#e9dfd3':n<2?'#dfc4ad':n<4?'#c79e7e':n<6?'#aa7858':'#83553c';
['2023','2024'].forEach(year=>{const wrap=document.createElement('div');wrap.className='heatmap-year';const label=document.createElement('strong');label.textContent=year;wrap.appendChild(label);const grid=document.createElement('div');grid.className='heatmap-grid';wrap.appendChild(grid);$('#heatmap').appendChild(wrap);let previous='';D.weeks.filter(r=>r.start.startsWith(year)).forEach((r,i)=>{const slot=document.createElement('div');slot.className='week-wrap';const month=r.start.slice(5,7);if(month!==previous){const tag=document.createElement('span');tag.className='month-tag';tag.textContent=Number(month)+'月';slot.appendChild(tag);}previous=month;const b=document.createElement('button');b.className='week-cell'+(r.streak?' streak':'');b.style.setProperty('--cell',color(r.count));b.style.setProperty('--delay',i*24+'ms');b.setAttribute('aria-label',r.start+'至'+r.end+'，'+r.count+'条'+(r.partial?'，窗口内部分周':''));b.dataset.start=r.start;b.dataset.count=r.count;b.dataset.streak=r.streak;b.title=r.start+' — '+r.end+' / '+r.count+'条';interact(b,()=>{if(selectedWeek)selectedWeek.classList.remove('selected');selectedWeek=b;b.classList.add('selected');readout($('#week-detail'),[r.start+' — '+r.end,r.count+'条作品',(r.streak?'连续28周区间':'')+(r.partial?' · 窗口内部分周':'')]);});slot.appendChild(b);grid.appendChild(slot);});});
const ms=$('#milestone-chart'),mx0=70,mx1=970,my0=28,my1=295,base=Date.parse(D.milestones[0].date+'T00:00:00+08:00'),last=Date.parse(D.milestones[2].date+'T00:00:00+08:00'),mx=d=>mx0+(Date.parse(d+'T00:00:00+08:00')-base)/(last-base)*(mx1-mx0),my=v=>my1-v/18*(my1-my0);
const defs=el('defs',{},ms),gr=el('linearGradient',{id:'milestone-fill',x1:0,y1:0,x2:0,y2:1},defs);el('stop',{offset:0,'stop-color':'#d9bda4','stop-opacity':'.4'},gr);el('stop',{offset:1,'stop-color':'#d9bda4','stop-opacity':'0'},gr);
[0,5,10,15].forEach(v=>{line(ms,mx0,my(v),mx1,my(v),{'stroke-dasharray':'2 7'});txt(ms,mx0-17,my(v)+4,v+'万',{'text-anchor':'end'});});
const pts=D.milestones.map(r=>({x:mx(r.date),y:my(r.fans)}));let path='M'+pts[0].x+' '+pts[0].y;for(let i=1;i<pts.length;i++)path+='H'+pts[i].x+'V'+pts[i].y;
el('path',{d:path+'V'+my1+'H'+pts[0].x+'Z',fill:'url(#milestone-fill)',class:'milestone-area'},ms);el('path',{d:path,class:'milestone-line'},ms);pts.forEach((p,i)=>{line(ms,p.x,p.y,p.x,my1,{stroke:'#d8b6a0','stroke-dasharray':'2 6'});el('circle',{cx:p.x,cy:p.y,r:7,fill:'#f7f2ec',stroke:'#a4775a','stroke-width':2},ms);txt(ms,p.x,p.y-20,'约'+D.milestones[i].fans+'万',{'text-anchor':i===0?'start':i===2?'end':'middle',style:'fill:#8c644d;font-family:Songti SC,serif;font-size:13px'});});
let selectedHigh=null;
